const src = $('Telegram Trigger').first().json;
const question = src.message?.text?.trim() || '';
const chatId = src.message?.chat?.id;
if (!question || !chatId) throw new Error('Only Telegram text messages are supported');
const html = String($json.data ?? $json.body ?? '');
const decode = s => s.replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&#8211;|&ndash;/gi,'–').replace(/&#8212;|&mdash;/gi,'—').replace(/&#39;|&apos;/gi,"'").replace(/&quot;/gi,'\"').replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(Number(n)));
const strip = s => decode(s.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim());
const links = [];
const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = re.exec(html))) {
  try {
    const url = new URL(m[1], 'https://sfiord.com/sup/');
    const title = strip(m[2]);
    if (url.hostname === 'sfiord.com' && title && !url.pathname.match(/\.(jpg|jpeg|png|gif|webp|svg|pdf|zip)$/i)) links.push({title, url: url.href.split('#')[0]});
  } catch {}
}
const unique = [...new Map(links.map(x => [x.url, x])).values()].slice(0, 180);
return [{json:{question,chatId,indexText:strip(html).slice(0,18000),links:unique}}];

const base = $('Extract Index').first().json;
const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
let urls = [];
try { urls = JSON.parse(text); } catch { urls = [...text.matchAll(/https?:\/\/[^\s\"']+/g)].map(m=>m[0]); }
const allowed = new Set(base.links.map(x=>x.url));
urls = [...new Set(urls)].filter(u=>allowed.has(u)).slice(0,3);
if (!urls.length) return [{json:{url:'https://sfiord.com/sup/',question:base.question,chatId:base.chatId,title:'خدمات و پشتیبانی'}}];
return urls.map(url=>({json:{url,question:base.question,chatId:base.chatId,title:base.links.find(x=>x.url===url)?.title || url}}));

const route = $('Prepare Article URLs').all();
const pages = $input.all().map((item,i)=>{
  const html = String(item.json.data ?? item.json.body ?? '');
  const text = html.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(Number(n))).replace(/\s+/g,' ').trim().slice(0,18000);
  return 'SOURCE: '+route[i].json.url+'\nTITLE: '+route[i].json.title+'\nCONTENT: '+text;
});
return [{json:{question:route[0].json.question,chatId:route[0].json.chatId,context:pages.join('\n\n---\n\n')}}];
